use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(
    ids: Vec<u32>,
    fetch: ai_task_support::Fetcher,
    deadline: std::time::Duration,
) -> Result<u64, SolveError> {
    let work = async move {
        let mut sum: u64 = 0;
        let mut rest = ids.into_iter();
        loop {
            let wave: Vec<u32> = rest.by_ref().take(4).collect();
            if wave.is_empty() {
                break;
            }
            let batch = wave.into_iter().map(|id| {
                let fetch = fetch.clone();
                async move { (id, fetch.fetch(id).await) }
            });
            for (id, result) in join_all_bounded(4, batch).await {
                match result {
                    Ok(value) => sum += value,
                    Err(_) => return Err(SolveError::Fetch { id }),
                }
            }
        }
        Ok(sum)
    };

    match timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time::timeout;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

const MAX_IN_FLIGHT: usize = 4;

pub async fn solve(
    ids: Vec<u32>,
    fetch: Fetcher,
    deadline: Duration,
) -> Result<u64, SolveError> {
    match timeout(deadline, run(ids, fetch)).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}

async fn run(ids: Vec<u32>, fetch: Fetcher) -> Result<u64, SolveError> {
    let mut pending = ids.into_iter();
    let mut sum: u64 = 0;

    loop {
        let wave: Vec<u32> = pending.by_ref().take(MAX_IN_FLIGHT).collect();
        if wave.is_empty() {
            break;
        }

        let fetches: Vec<_> = wave
            .into_iter()
            .map(|id| {
                let fetch = fetch.clone();
                async move {
                    match fetch.fetch(id).await {
                        Ok(value) => Ok::<u64, u32>(value),
                        Err(_) => Err::<u64, u32>(id),
                    }
                }
            })
            .collect();

        for result in join_all_bounded(MAX_IN_FLIGHT, fetches).await {
            match result {
                Ok(value) => sum += value,
                Err(id) => return Err(SolveError::Fetch { id }),
            }
        }
    }

    Ok(sum)
}

use std::time::Duration;

use ai_task_support::Fetcher;
use lgwks_bot::rt::task::join_all_bounded;
use lgwks_bot::rt::time;

#[derive(Debug)]
pub enum SolveError {
    Fetch { id: u32 },
    Deadline,
    Cancelled,
}

pub async fn solve(ids: Vec<u32>, fetch: Fetcher, deadline: Duration) -> Result<u64, SolveError> {
    let work = async move {
        let mut sum: u64 = 0;
        let mut next: usize = 0;
        while next < ids.len() {
            let end = (next + 4).min(ids.len());
            let futures: Vec<_> = ids[next..end]
                .iter()
                .map(|&id| {
                    let fetcher = fetch.clone();
                    async move { fetcher.fetch(id).await.map_err(|_| SolveError::Fetch { id }) }
                })
                .collect();
            let results = join_all_bounded(4, futures).await;
            next = end;
            for result in results {
                sum = sum.saturating_add(result?);
            }
        }
        Ok(sum)
    };

    match time::timeout(deadline, work).await {
        Ok(result) => result,
        Err(_) => Err(SolveError::Deadline),
    }
}
